import json
rows=[json.loads(l) for l in open('sesja-1.jsonl')]
def res(i):
    r=rows[i]
    c=r['message']['content']
    if isinstance(c,list):
        for b in c:
            if b.get('type')=='tool_result':
                cc=b['content']; 
                if isinstance(cc,list): cc=' '.join(x.get('text','') for x in cc)
                return cc
for i in range(570,650):
    r=rows[i]
    if r.get('type')=='assistant':
        for b in r['message']['content']:
            if b.get('type')=='text': print(i,'ASSISTANT TEXT:',b['text'][:3000]);print('---')
            if b.get('type')=='tool_use': print(i,'TOOL',json.dumps(b['input'],ensure_ascii=False)[:600]);print('---')
    elif r.get('type')=='user':
        t=res(i)
        if t: print(i,'RESULT:',t[:1200]);print('---')
